select case when unit_price >= 410 then 'high' when unit_price >= 50 then 'mid' else 'low' end as unit_price_bucket, sum(unit_price * quantity) as revenue, count(*) as cnt, round(stddev(unit_price), 2) as stddev_unit_price from order_items where unit_price between 230 and 360 and unit_price < 130 and unit_price <= 270 group by case when unit_price >= 410 then 'high' when unit_price >= 50 then 'mid' else 'low' end order by stddev_unit_price desc;
